5: /// <summary>
6: /// The process-environment variables the CLI strategies read to choose their temporary folder, in each strategy's
7: /// fallback order: <c>CliBrainSlotChatClient</c> reads MCPSERVER_QUADBRAIN_CLI_TEMP then MCPSERVER_ONESHOT_TEMP;
8: /// <c>CodexCliAgentExecutionStrategy</c> reads MCPSERVER_CODEX_ONESHOT_TEMP then MCPSERVER_CODEX_TRIAGE_TEMP;
9: /// <c>OneShotCliAgentExecutionStrategy</c> reads MCPSERVER_ONESHOT_TEMP, MCPSERVER_CODEX_ONESHOT_TEMP, then
10: /// MCPSERVER_CODEX_TRIAGE_TEMP; <c>GrokCliAgentExecutionStrategy</c> reads MCPSERVER_GROK_ONESHOT_TEMP then
11: /// MCPSERVER_ONESHOT_TEMP. A test that reaches one of them sets every name of the chain and restores it: the name the
12: /// strategy under test reads first points at the test folder and every other name at a separate test-owned fallback
13: /// folder, so an assertion on the test folder proves the primary name won over a set fallback (TR-MCP-USECASE-018
14: /// AC-006 and TR-MCP-USECASE-019 AC-008 as amended 2026-10-26; operator: "Strengthen AC, move 14 (Recommended)" and
15: /// "Dependence + proof AC (Recommended)"; hostile validation finding R6-F1). Shared by the three strategy test classes.
16: /// </summary>
17: internal static class CliTempVariables
18: {
19:     /// <summary>Every name of the four fallback chains, once each.</summary>
20:     internal static IReadOnlyList<string> Names { get; } =
21:     [
22:         "MCPSERVER_QUADBRAIN_CLI_TEMP",
23:         "MCPSERVER_ONESHOT_TEMP",
24:         "MCPSERVER_CODEX_ONESHOT_TEMP",
25:         "MCPSERVER_CODEX_TRIAGE_TEMP",
26:         "MCPSERVER_GROK_ONESHOT_TEMP",
27:     ];
28: 
29:     /// <summary>
30:     /// Runs <paramref name="body"/> with <paramref name="primaryName"/> pointing at a new test folder and every other
31:     /// name of <see cref="Names"/> at a second new fallback folder, both under the official temporary folder, then
32:     /// restores every name to its earlier value (an unset name stays unset) and deletes both folders, also when the
33:     /// body throws. Callers belong to <see cref="ProcessEnvironmentCollection"/>.
34:     /// </summary>
35:     /// <param name="primaryName">The name the strategy under test reads first; one of <see cref="Names"/>.</param>
36:     /// <param name="body">The test body; it receives the test folder.</param>
37:     /// <returns>A task that completes when the body has run and the variables are restored.</returns>
38:     internal static Task RunWithTestFolderAsync(string primaryName, Func<string, Task> body)
39:     {
40:         ArgumentNullException.ThrowIfNull(body);
41:         return RunWithTestFoldersAsync(primaryName, (folder, _) => body(folder));
42:     }
43: 
44:     /// <summary>
45:     /// The same as <see cref="RunWithTestFolderAsync"/>, with the body receiving the fallback folder too.
46:     /// </summary>
47:     /// <param name="primaryName">The name the strategy under test reads first; one of <see cref="Names"/>.</param>
48:     /// <param name="body">The test body; it receives the test folder and the fallback folder.</param>
49:     /// <returns>A task that completes when the body has run and the variables are restored.</returns>
50:     internal static async Task RunWithTestFoldersAsync(string primaryName, Func<string, string, Task> body)
51:     {
52:         ArgumentNullException.ThrowIfNull(body);
53:         if (!Names.Contains(primaryName, StringComparer.Ordinal))
54:             throw new ArgumentException($"{primaryName} is not a CLI temp variable name.", nameof(primaryName));
55: 
56:         var previous = Snapshot();
57:         var stem = Path.Combine(Path.GetTempPath(), "qbt-cli-temp-" + Guid.NewGuid().ToString("N"));
58:         var folder = stem + "-primary";
59:         var fallbackFolder = stem + "-fallback";
60:         Directory.CreateDirectory(folder);
61:         Directory.CreateDirectory(fallbackFolder);
62:         try
63:         {
64:             foreach (var name in Names)
65:                 Environment.SetEnvironmentVariable(name, name == primaryName ? folder : fallbackFolder);
66:             await body(folder, fallbackFolder).ConfigureAwait(true);
67:         }
68:         finally
69:         {
70:             foreach (var (name, value) in previous)
71:                 Environment.SetEnvironmentVariable(name, value);
72:             foreach (var created in new[] { folder, fallbackFolder })
73:             {
74:                 try
75:                 {
76:                     Directory.Delete(created, recursive: true);
77:                 }
78:                 catch (IOException)
79:                 {
80:                 }
81:             }
82:         }
83:     }
84: 
85:     /// <summary>Reads the current value of every name of <see cref="Names"/> from the process environment.</summary>
86:     /// <returns>The values by name, null for an unset name.</returns>
87:     internal static Dictionary<string, string?> Snapshot() =>
88:         Names.ToDictionary(name => name, name => Environment.GetEnvironmentVariable(name), StringComparer.Ordinal);
89: 
90:     /// <summary>
91:     /// Asserts that a snapshot of the variables points the name a strategy reads first, <paramref name="primaryName"/>,
92:     /// at <paramref name="folder"/> and every other name of <see cref="Names"/> at a different folder,
93:     /// <paramref name="fallbackFolder"/>, so a test that asserts on <paramref name="folder"/> proves the primary name
94:     /// won over a set fallback.
95:     /// </summary>
96:     /// <param name="observed">The variable values seen, by name.</param>
97:     /// <param name="primaryName">The name the strategy under test reads first; one of <see cref="Names"/>.</param>
98:     /// <param name="folder">The folder the primary name must point at.</param>
99:     /// <param name="fallbackFolder">The folder every other name must point at; not <paramref name="folder"/>.</param>
100:     internal static void AssertChainAt(IReadOnlyDictionary<string, string?> observed, string primaryName, string folder, string fallbackFolder)
101:     {
102:         ArgumentNullException.ThrowIfNull(observed);
103:         Assert.Contains(primaryName, Names);
104:         Assert.NotEqual(folder, fallbackFolder);
105:         foreach (var name in Names)
106:         {
107:             Assert.True(observed.TryGetValue(name, out var value), $"{name} was not observed.");
108:             Assert.Equal(name == primaryName ? folder : fallbackFolder, value);
109:         }
110:     }
111: 
112:     /// <summary>
113:     /// Asserts that every name of <see cref="Names"/> holds the same value after a run as before it, an unset name
114:     /// included.
115:     /// </summary>
116:     /// <param name="before">The values before the run, by name.</param>
117:     /// <param name="after">The values after the run, by name.</param>
118:     internal static void AssertRestored(IReadOnlyDictionary<string, string?> before, IReadOnlyDictionary<string, string?> after)
119:     {
120:         ArgumentNullException.ThrowIfNull(before);
121:         ArgumentNullException.ThrowIfNull(after);
122:         foreach (var name in Names)
123:         {
124:             Assert.True(before.TryGetValue(name, out var expected), $"{name} was not recorded before the run.");
125:             Assert.True(after.TryGetValue(name, out var actual), $"{name} was not recorded after the run.");
126:             Assert.Equal(expected, actual);
127:         }
128:     }
129: }
