580: +
581: +        using var process = Process.Start(start) ?? throw new InvalidOperationException("Could not start docker.");
582: +        var output = process.StandardOutput.ReadToEndAsync();
583: +        var error = process.StandardError.ReadToEndAsync();
584: +        if (!process.WaitForExit(TimeSpan.FromMinutes(2)))
585: +        {
586: +            process.Kill(entireProcessTree: true);
