8: /// <summary>
9: /// Boots an ephemeral PostgreSQL cluster with generated credentials on a free port for the
10: /// lifetime of a test class, so PostgreSQL migration tests run everywhere without skip mechanics
11: /// (Byrd V4: gates pass or fail directly). Honors <c>MCP_TEST_POSTGRES_CONNECTION</c> as an
12: /// external-server override; otherwise requires local PostgreSQL binaries (an installation under
13: /// Program Files, or the portable set provisioned by the <c>InstallTestDependencies</c> Nuke
14: /// target) and fails with that remediation hint when none are found.
15: /// </summary>
16: public sealed class EphemeralPostgresFixture : IDisposable
17: {
18:     private readonly string? _pgBin;
19:     private readonly string? _dataDir;
20: 
21:     /// <summary>Server-level connection string (no specific database).</summary>
22:     public string ServerConnectionString { get; }
23: 
24:     /// <summary>Starts the cluster (or adopts the externally supplied server).</summary>
25:     public EphemeralPostgresFixture()
26:     {
27:         var external = Environment.GetEnvironmentVariable("MCP_TEST_POSTGRES_CONNECTION");
28:         if (!string.IsNullOrWhiteSpace(external))
29:         {
30:             ServerConnectionString = external;
31:             return;
32:         }
33: 
34:         _pgBin = FindPostgresBinaries()
35:             ?? throw new InvalidOperationException(
36:                 "PostgreSQL binaries not found (Program Files\\PostgreSQL\\*\\bin or the test-tools directory). " +
37:                 "Run the 'InstallTestDependencies' Nuke target, or set MCP_TEST_POSTGRES_CONNECTION.");
38: 
39:         _dataDir = Path.Combine(Path.GetTempPath(), $"mcp-test-pgdata-{Guid.NewGuid():N}");
40:         var password = Convert.ToHexString(RandomNumberGenerator.GetBytes(12));
41:         var port = GetFreeTcpPort();
42: 
43:         var passwordFile = Path.Combine(Path.GetTempPath(), $"mcp-test-pgpw-{Guid.NewGuid():N}.txt");
44:         File.WriteAllText(passwordFile, password);
45:         try
46:         {
47:             RunTool(
48:                 Path.Combine(_pgBin, "initdb.exe"),
49:                 $"-D \"{_dataDir}\" -U mcptest --auth=scram-sha-256 --pwfile=\"{passwordFile}\" -E UTF8",
50:                 captureOutput: true);
51:         }
52:         finally
53:         {
54:             File.Delete(passwordFile);
55:         }
56: 
57:         // pg_ctl must run without output redirection: the postgres child inherits redirected
58:         // handles and the pipe never closes, hanging the caller even after -w returns. It therefore
59:         // writes to this test process's standard output, which carries the xUnit v3 JSON messages, so it
60:         // runs silent (-s); its informational lines garbled those messages and lost test results.
61:         RunTool(Path.Combine(_pgBin, "pg_ctl.exe"), PgCtlStartArguments(_dataDir, port, Path.Combine(_dataDir, "pg.log")));
62: 
63:         ServerConnectionString = $"Host=localhost;Port={port};Username=mcptest;Password={password};Database=postgres";
64:     }
