110:     private static string? FindPostgresBinaries()
111:     {
112:         var installedRoot = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles), "PostgreSQL");
113:         if (Directory.Exists(installedRoot))
114:         {
115:             var installedBin = Directory
116:                 .EnumerateDirectories(installedRoot)
117:                 .OrderByDescending(d => d)
118:                 .Select(d => Path.Combine(d, "bin"))
119:                 .FirstOrDefault(bin => File.Exists(Path.Combine(bin, "initdb.exe")));
120:             if (installedBin is not null)
121:                 return installedBin;
122:         }
123: 
124:         var toolsBin = Path.Combine(
125:             Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
126:             "QBrainAi", "test-tools", "pgsql", "bin");
127:         return File.Exists(Path.Combine(toolsBin, "initdb.exe")) ? toolsBin : null;
