130:     private static void RunTool(string fileName, string arguments, bool captureOutput = false)
131:     {
132:         var cwd = Path.GetDirectoryName(fileName);
133:         if (string.IsNullOrWhiteSpace(cwd))
134:         {
135:             cwd = Environment.CurrentDirectory;
136:         }
137: 
138:         var capture = captureOutput
139:             || Path.GetFileName(fileName).Equals("initdb.exe", StringComparison.OrdinalIgnoreCase);
140:         var startInfo = new ProcessStartInfo
141:         {
142:             FileName = fileName,
143:             Arguments = arguments,
144:             WorkingDirectory = cwd,
145:             UseShellExecute = false,
146:             RedirectStandardOutput = capture,
147:             RedirectStandardError = capture,
148:         };
149:         var process = Process.Start(startInfo)
150:             ?? throw new InvalidOperationException($"Failed to start {Path.GetFileName(fileName)}.");
151:         var stdout = capture ? process.StandardOutput.ReadToEnd() : string.Empty;
152:         var stderr = capture ? process.StandardError.ReadToEnd() : string.Empty;
153:         process.WaitForExit();
154:         if (process.ExitCode != 0)
155:         {
156:             var suffix = capture
157:                 ? $" arguments: {SanitizeEvidence(arguments)}. cwd: {SanitizeEvidence(cwd)}. stdout: {SanitizeEvidence(stdout)}. stderr: {SanitizeEvidence(stderr)}."
158:                 : string.Empty;
159:             throw new InvalidOperationException(
160:                 $"{Path.GetFileName(fileName)} failed with exit code {process.ExitCode}.{suffix}");
161:         }
162:     }
163: 
164:     private static string SanitizeEvidence(string value)
165:     {
166:         if (string.IsNullOrEmpty(value))
167:         {
168:             return value;
169:         }
